#!/bin/bash
# Verify the working tree builds and its lockfiles agree with the manifests.
set -u
fail=0
cargo metadata --locked --format-version 1 --no-deps >/dev/null 2>&1 || { echo "FAIL cargo metadata --locked"; fail=1; }
pnpm install --frozen-lockfile --lockfile-only >/dev/null 2>&1 || { echo "FAIL pnpm frozen lockfile"; fail=1; }
cargo fmt --check >/dev/null 2>&1 || { echo "FAIL cargo fmt --check"; fail=1; }
cargo test -p caliper-docgen-core --no-run >/dev/null 2>&1 || { echo "FAIL cargo test --no-run"; fail=1; }
[ $fail -eq 0 ] && echo "VERIFY OK"
exit $fail

